def _cov_query(c, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(c, p, buf, cap)
    if n < 0:
        raise AraelError(
            n, (_f.fit_cov_error(c) or b"").decode())
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """An assembled covariance, OWNED: released on garbage
    collection (free() to force it), independent of later assemblies.
    Per-entity queries (marginal/conditional by param count: 1 ->
    float, 2/3 -> matrix2d/3d, larger -> row-major tuples). Entity
    arguments must come from the live model."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def free(self):
        if self._h:
            _f.fit_cov_free(self._h)
            self._h = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def marginal(self, e):
        """The entity's marginal covariance block."""
        if isinstance(e, N):
            return (_shape_1)(_cov_query(self._h, _f.fit_n_marginal_cov, e._p, 1))
        if isinstance(e, Pose):
            return (lambda b: _shape_n(b, 7))(_cov_query(self._h, _f.fit_pose_marginal_cov, e._p, 49))
        if isinstance(e, Rig):
            return (lambda b: _shape_n(b, 7))(_cov_query(self._h, _f.fit_rig_marginal_cov, e._p, 49))
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        if isinstance(e, N):
            return (_shape_1)(_cov_query(self._h, _f.fit_n_conditional_cov, e._p, 1))
        if isinstance(e, Pose):
            return (lambda b: _shape_n(b, 7))(_cov_query(self._h, _f.fit_pose_conditional_cov, e._p, 49))
        if isinstance(e, Rig):
            return (lambda b: _shape_n(b, 7))(_cov_query(self._h, _f.fit_rig_conditional_cov, e._p, 49))
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        if isinstance(e, N):
            return list(_cov_query(self._h, _f.fit_n_std_dev, e._p, 1))
        if isinstance(e, Pose):
            return list(_cov_query(self._h, _f.fit_pose_std_dev, e._p, 7))
        if isinstance(e, Rig):
            return list(_cov_query(self._h, _f.fit_rig_std_dev, e._p, 7))
        raise TypeError("no std_dev for %r" % (e,))
    def _cross_n_n(self, a, b):
        buf = (ctypes.c_double * 1)()
        rows = _f.fit_n_n_cross_cov(self._h, a._p, b._p, buf, 1)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 1 + c] for c in range(1))
                     for r in range(rows))
    def _cross_n_pose(self, a, b):
        buf = (ctypes.c_double * 7)()
        rows = _f.fit_n_pose_cross_cov(self._h, a._p, b._p, buf, 7)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 7 + c] for c in range(7))
                     for r in range(rows))
    def _cross_n_rig(self, a, b):
        buf = (ctypes.c_double * 7)()
        rows = _f.fit_n_rig_cross_cov(self._h, a._p, b._p, buf, 7)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 7 + c] for c in range(7))
                     for r in range(rows))
    def _cross_pose_n(self, a, b):
        buf = (ctypes.c_double * 7)()
        rows = _f.fit_pose_n_cross_cov(self._h, a._p, b._p, buf, 7)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 1 + c] for c in range(1))
                     for r in range(rows))
    def _cross_pose_pose(self, a, b):
        buf = (ctypes.c_double * 49)()
        rows = _f.fit_pose_pose_cross_cov(self._h, a._p, b._p, buf, 49)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 7 + c] for c in range(7))
                     for r in range(rows))
    def _cross_pose_rig(self, a, b):
        buf = (ctypes.c_double * 49)()
        rows = _f.fit_pose_rig_cross_cov(self._h, a._p, b._p, buf, 49)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 7 + c] for c in range(7))
                     for r in range(rows))
    def _cross_rig_n(self, a, b):
        buf = (ctypes.c_double * 7)()
        rows = _f.fit_rig_n_cross_cov(self._h, a._p, b._p, buf, 7)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 1 + c] for c in range(1))
                     for r in range(rows))
    def _cross_rig_pose(self, a, b):
        buf = (ctypes.c_double * 49)()
        rows = _f.fit_rig_pose_cross_cov(self._h, a._p, b._p, buf, 49)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 7 + c] for c in range(7))
                     for r in range(rows))
    def _cross_rig_rig(self, a, b):
        buf = (ctypes.c_double * 49)()
        rows = _f.fit_rig_rig_cross_cov(self._h, a._p, b._p, buf, 49)
        if rows < 0:
            raise AraelError(
                rows, (_f.fit_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 7 + c] for c in range(7))
                     for r in range(rows))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        if isinstance(a, N) and isinstance(b, N):
            return self._cross_n_n(a, b)
        if isinstance(a, N) and isinstance(b, Pose):
            return self._cross_n_pose(a, b)
        if isinstance(a, N) and isinstance(b, Rig):
            return self._cross_n_rig(a, b)
        if isinstance(a, Pose) and isinstance(b, N):
            return self._cross_pose_n(a, b)
        if isinstance(a, Pose) and isinstance(b, Pose):
            return self._cross_pose_pose(a, b)
        if isinstance(a, Pose) and isinstance(b, Rig):
            return self._cross_pose_rig(a, b)
        if isinstance(a, Rig) and isinstance(b, N):
            return self._cross_rig_n(a, b)
        if isinstance(a, Rig) and isinstance(b, Pose):
            return self._cross_rig_pose(a, b)
        if isinstance(a, Rig) and isinstance(b, Rig):
            return self._cross_rig_rig(a, b)
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


class Jacobian:
    """A computed Jacobian, OWNED: released on garbage collection
    (free() to force it). A snapshot of the parameters at the call;
    later solves or edits do not touch it."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def free(self):
        if self._h:
            _f.fit_jac_free(self._h)
            self._h = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    @property
    def num_residuals(self):
        """Number of residual rows."""
        return _f.fit_jac_num_residuals(self._h)

    @property
    def num_params(self):
        """Number of parameter columns."""
        return _f.fit_jac_num_params(self._h)

    def singular_values(self, column_normalised=False):
        """Singular values, descending, always f64 (near-zero
        values count the free DOF). column_normalised scales each
        column to unit L2 norm first, so the spectrum reflects
        row-space rank alone, not per-parameter scale."""
        return self._vals(
            lambda buf, cap: _f.fit_jac_singular_values(
                self._h, column_normalised, buf, cap))

    def column_l2_norms(self):
        """L2 norm of each Jacobian column, in parameter-index
        order."""
        return self._vals(
            lambda buf, cap: _f.fit_jac_column_l2_norms(
                self._h, buf, cap))

    def _vals(self, fn):
        def ck(n):
            if n < 0:
                raise AraelError(
                    n, (_f.fit_jac_error(self._h) or b"").decode())
            return n
        n = ck(fn(None, 0))
        if n == 0:
            return []
        buf = (ctypes.c_double * n)()
        ck(fn(buf, n))
        return list(buf)


class FitObsVec:
    """View of `obs` (vec of Obs); element wrappers re-resolve
    their pointer by key on every access, so growing the collection
    cannot leave them dangling. Mutating while iterating is undefined."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.fit_obs_len(self._p)

    def reserve(self, additional):
        _f.fit_obs_reserve(self._p, additional)

    def __getitem__(self, i):
        n = len(self)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        return Obs(lambda i=i: _f.fit_obs_at(self._p, i))

    def __iter__(self):
        for i in range(len(self)):
            yield Obs(lambda i=i: _f.fit_obs_at(self._p, i))

    def clear(self):
        _f.fit_obs_clear(self._p)

    def truncate(self, n):
        _f.fit_obs_truncate(self._p, n)

    def push(self):
        _f.fit_obs_push(self._p)
        return self[len(self) - 1]

    def pop(self):
        """Drops the last element; False when already empty."""
        return _f.fit_obs_pop(self._p)


