class Fit:
    """The model. Owns the underlying Rust instance; free() (or GC)
    releases it. One model, one thread."""

    def __init__(self):
        load()
        self._p = _f.fit_new()

    def free(self):
        if self._p:
            _f.fit_free(self._p)
            self._p = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def _solved(self, code, res):
        if code < 0:
            raise AraelError(code, _err(self._p),
                             res if res._detail else None)
        return res

    def solve_dense(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.fit_solve_dense(self._p, ctypes.byref(cfg),
                                     ctypes.byref(r)), r)

    def solve_sparse(self, cfg=None, opts=None):
        """Sparse solve; `opts` (a SparseOptions) selects the
        backend's route, None means the defaults."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.fit_solve_sparse(
                self._p, ctypes.byref(cfg),
                ctypes.byref(opts) if opts is not None else None,
                ctypes.byref(r)), r)

    def solve_band(self, kd, cfg=None):
        """Band Cholesky solve; kd is the half-bandwidth in scalar
        parameters."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.fit_solve_band(self._p, kd, ctypes.byref(cfg),
                                    ctypes.byref(r)), r)

    def assemble_covariance(self, mode=CovMode.ALL_MARGINALS):
        c = ctypes.c_void_p()
        code = _f.fit_assemble_covariance(self._p, int(mode),
                                                ctypes.byref(c))
        if code != 0:
            raise AraelError(code, _err(self._p))
        return Covariance(c)

    def cost(self):
        """Total cost at the current parameter values (no solve)."""
        return _f.fit_cost(self._p)

    def cost_table(self):
        """Per-constraint cost breakdown at the current parameters:
        {label: that group's robustified cost} (a `loss` applied;
        the label is `name` on the constraint attribute, else the
        struct name). The table sums to cost(). Raises on a
        panic."""
        n = _f.fit_cost_table(self._p)
        if n < 0:
            raise AraelError(n, _err(self._p))
        return {
            _f.fit_cost_table_name(self._p, i).decode():
                _f.fit_cost_table_value(self._p, i)
            for i in range(n)
        }

    def calc_jacobian(self):
        """The sparse Jacobian at the current parameters (a
        snapshot). Raises on a panic."""
        j = ctypes.c_void_p()
        code = _f.fit_calc_jacobian(self._p, ctypes.byref(j))
        if code != 0:
            raise AraelError(code, _err(self._p))
        return Jacobian(j)

    def validate(self):
        """Empty string when the model is clean, the diagnostic text
        otherwise."""
        return _f.fit_validate(self._p).decode()

    def last_error(self):
        return _err(self._p)

    @property
    def m(self):
        return _f.fit_m(self._p)

    @m.setter
    def m(self, v):
        _f.fit_set_m(self._p, v)

    @property
    def m_optimize(self):
        return _f.fit_m_optimize(self._p)

    @m_optimize.setter
    def m_optimize(self, v):
        _f.fit_m_set_optimize(self._p, bool(v))

    @property
    def c(self):
        return _f.fit_c(self._p)

    @c.setter
    def c(self, v):
        _f.fit_set_c(self._p, v)

    @property
    def c_optimize(self):
        return _f.fit_c_optimize(self._p)

    @c_optimize.setter
    def c_optimize(self, v):
        _f.fit_c_set_optimize(self._p, bool(v))

    @property
    def cal(self):
        return _f.fit_cal(self._p)

    @cal.setter
    def cal(self, v):
        _f.fit_set_cal(self._p, v if isinstance(v, _m.vect2d) else _m.vect2d(v))

    # field `tag`: String -- opaque, no accessor generated

    @property
    def obs(self):
        return FitObsVec(self._p)

    @property
    def items(self):
        return FitItemsVec(self._p)

    @property
    def poses(self):
        return FitPosesDeque(self._p)

    @property
    def ties(self):
        return FitTiesVec(self._p)

    @property
    def marks(self):
        return FitMarksArena(self._p)

    @property
    def rigs(self):
        return FitRigsVec(self._p)

